use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        1 <= k,
        k < list.len(),
    ensures
        new_list.len() == list.len() - 1,

        forall|i: int|
            0 <= i && i < (k as int) - 1
            ==> new_list[i] == list[i],

        forall|i: int|
            (k as int) - 1 <= i && i < new_list.len()
            ==> new_list[i] == list[i + 1],

        new_list@ ==
            list@.subrange(0, (k as int) - 1)
              + list@.subrange(k as int, list.len() as int),
{
    let mut out: Vec<i32> = Vec::new();
    let remove_idx: usize = k - 1;

    let mut i: usize = 0;
    while i < list.len()
        invariant
            i <= list.len(),
            out.len() == if i <= remove_idx { i } else { i - 1 },
            out@ == list@.subrange(0, if i <= remove_idx { i as int } else { remove_idx as int })
                 + list@.subrange(remove_idx as int + 1, i as int),
    {
        if i != remove_idx {
            out.push(list[i]);
        }
        i = i + 1;
    }

    // At loop end, i == list.len(), so the invariant gives the desired concatenation property.
    out
}

} // verus!